    <link rel="preload" as="style" href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap" onload="this.onload=null;this.rel='stylesheet'">
    <noscript>
        <link href="https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&display=optional" rel="stylesheet">
        <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">
    </noscript>

    <style>
        * { font-family: 'Inter', system-ui, -apple-system, sans-serif; }
        .font-display { font-family: 'Amiri', Georgia, serif; }
        .font-mono-brand { font-family: 'IBM Plex Mono', monospace; }

        .animated-bg { background: linear-gradient(120deg, #faf6ec 0%, #efe6d0 50%, #f5e9c4 100%); }
        .glass-navbar {
            background: rgba(250, 246, 236, 0.9);
            backdrop-filter: blur(12px);
            border-bottom: 1px solid rgba(201, 162, 39, 0.25);
        }

        /* Animasi */
        .floating { animation: float 6s ease-in-out infinite; }
        .float-delay-1 { animation-delay: 1s; }
        .float-delay-2 { animation-delay: 2.5s; }
        @keyframes float {
            0%, 100% { transform: translateY(0) rotate(0deg); }
            50% { transform: translateY(-15px) rotate(2deg); }
        }

        .pulse-countdown { position: relative; }
        .pulse-countdown::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: 9999px;
            background: rgba(201, 162, 39, 0.45);
            animation: pulseGlow 2s infinite;
            pointer-events: none;
        }
        @keyframes pulseGlow {
            0% { transform: scale(1); opacity: 0.45; }
            70%, 100% { transform: scale(1.6); opacity: 0; }
        }

        .reveal { opacity: 0; transform: translateY(25px); transition: opacity .7s ease, transform .7s ease; }
        .reveal.visible { opacity: 1; transform: translateY(0); }

        /* Kartu sholat & tombol */
        .prayer-card { transition: all .3s cubic-bezier(.2, .9, .4, 1.1); }
        .ripple-btn { position: relative; overflow: hidden; }
        .ripple-btn::after {
            content: '';
            position: absolute;
            top: 50%; left: 50%;
            width: 0; height: 0;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.3);
            transform: translate(-50%, -50%);
            transition: width .4s, height .4s;
        }
        @media (hover: hover) and (pointer: fine) {
            .prayer-card:hover { transform: translateY(-8px) scale(1.02); box-shadow: 0 25px 35px -12px rgba(11, 61, 54, .2); }
            .ripple-btn:hover::after { width: 200%; height: 200%; }
        }

        /* Ornamen & ikon */
        .deco-floating { display: none; }
        @media (min-width: 640px) { .deco-floating { display: block; } }
        svg.mdi-icon { display: inline-block; vertical-align: -0.125em; flex-shrink: 0; }
        img { max-width: 100%; height: auto; display: block; }

        /* Scrollbar */
        ::-webkit-scrollbar { width: 8px; }
        ::-webkit-scrollbar-track { background: #efe6d0; }
        ::-webkit-scrollbar-thumb { background: #145c4f; border-radius: 20px; }

        /* Performa: lewati render section di luar layar */
        section:not(:first-of-type) { content-visibility: auto; contain-intrinsic-size: auto 800px; }
        footer { content-visibility: auto; contain-intrinsic-size: auto 300px; }

        .transition-fast {
            transition-property: transform, box-shadow, background-color, color, opacity;
            transition-timing-function: cubic-bezier(.4, 0, .2, 1);
            transition-duration: .3s;
        }

        @media (prefers-reduced-motion: reduce) {
            .floating, .pulse-countdown::after, .reveal { animation: none !important; transition: none !important; }
        }
    </style>
</head>

