                    <h3 class="font-bold text-xl text-gray-800 flex items-center gap-2"><svg class="mdi-icon text-gold-600" width="24" height="24" aria-hidden="true"><use href="#i-trophy"/></svg> Penghargaan Kedisiplinan</h3>
                    <p class="text-gray-600 mt-2 text-sm">Siswa dengan kehadiran sholat sempurna mendapat reward digital & sertifikat dari sekolah.</p>
                </div>
            </article>

            <article class="bg-white/90 rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-fast reveal delay-150 border border-sand">
                <div class="h-48 bg-teal-600/80 flex flex-col items-center justify-center text-center text-white font-bold text-xl relative" role="img" aria-label="Aplikasi Mobile Absensi Sholat">
                    <span>Mobile</span><span>App Absensi</span>
                    <span class="absolute top-2 left-2 bg-teal-800/80 text-xs font-medium px-2 py-1 rounded-full">Mobile Friendly</span>
                </div>
                <div class="p-5">
                    <h3 class="font-bold text-xl text-gray-800 flex items-center gap-2"><svg class="mdi-icon text-gold-600" width="24" height="24" aria-hidden="true"><use href="#i-globe"/></svg> Akses Web & Mobile</h3>
                    <p class="text-gray-600 mt-2 text-sm">Guru dan siswa dapat absen melalui dashboard web atau PWA. Fleksibel dari HP/laptop.</p>
                </div>
            </article>
        </div>
    </section>

    <!-- Jadwal Sholat -->
    <section class="max-w-6xl mx-auto px-5 py-8 pb-20 relative z-10">
        <div class="text-center mb-10 reveal">
            <h2 class="font-display text-3xl sm:text-4xl md:text-5xl font-extrabold text-gray-800">🕌 Jadwal Sholat<span class="text-teal-700"> Hari Ini</span></h2>
            <p class="text-gray-500 mt-2 text-sm sm:text-base">Lokasi: Padang, Sumatera Barat • Metode Kemenag RI</p>
            <div class="flex flex-wrap justify-center items-center gap-2 sm:gap-3 bg-white/90 rounded-full w-fit max-w-full mx-auto px-4 sm:px-5 py-2 mt-4 shadow-md border border-gold-200 font-mono-brand text-xs sm:text-sm">
                <svg class="mdi-icon text-teal-700" width="18" height="18" aria-hidden="true"><use href="#i-calendar"/></svg>
                <span id="gregorianDate" class="font-medium text-gray-700">Memuat...</span>
                <span class="mx-1 text-gold-500">•</span>
                <svg class="mdi-icon" width="16" height="16" aria-hidden="true"><use href="#i-moon"/></svg>
                <span id="hijriDate" class="font-medium text-gray-700">-</span>
            </div>
        </div>

        <div id="loadingPrayers" class="flex flex-col items-center justify-center py-16">
            <div class="relative w-20 h-20">
                <div class="absolute inset-0 rounded-full border-4 border-teal-200 border-t-teal-700 animate-spin"></div>
                <svg class="mdi-icon absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-teal-800" width="32" height="32" aria-hidden="true"><use href="#i-mosque"/></svg>
            </div>
            <p class="text-teal-800 font-medium mt-5">Mengambil jadwal sholat & waktu terkini...</p>
        </div>

        <div id="errorMessage" class="hidden bg-rose-50/90 border border-rose-200 rounded-2xl p-7 text-center max-w-md mx-auto shadow-lg">
            <svg class="mdi-icon text-rose-600 mx-auto" width="48" height="48" aria-hidden="true"><use href="#i-alert"/></svg>
            <p class="text-rose-700 font-bold mt-3">Gagal memuat jadwal sholat</p>
            <p class="text-rose-600 text-sm mt-1" id="errorDetail"></p>
            <button id="retryBtn" class="mt-5 bg-rose-50 hover:bg-rose-200 text-rose-700 px-6 py-2 rounded-full transition-fast font-semibold flex items-center gap-2 mx-auto min-h-[44px]">
                <svg class="mdi-icon" width="24" height="24" aria-hidden="true"><use href="#i-refresh"/></svg> Coba Lagi
            </button>
        </div>

        <div id="prayerContent" class="hidden">
            <div class="bg-gradient-to-br from-white to-teal-50/80 rounded-3xl p-5 sm:p-6 mb-12 shadow-xl border border-gold-200 transform transition-fast hover:shadow-2xl reveal relative overflow-hidden">
                <div class="flex flex-col md:flex-row justify-between items-center gap-5 relative z-10">
                    <div class="flex items-center gap-4">
                        <div class="bg-gold-100 rounded-full p-4 pulse-countdown shrink-0">
                            <svg class="mdi-icon text-gold-700" width="36" height="36" aria-hidden="true"><use href="#i-clock"/></svg>
                        </div>
                        <div>
                            <p class="text-xs sm:text-sm font-semibold text-teal-700 uppercase tracking-wider">⌛ Waktu Sholat Berikutnya</p>
                            <p id="nextPrayerName" class="font-display text-2xl sm:text-3xl font-black text-gray-800 mt-1">-</p>
                        </div>
                    </div>
                    <div class="text-center md:text-right">
                        <span id="nextPrayerTime" class="text-3xl sm:text-4xl font-mono-brand font-bold text-teal-800 bg-white/60 px-4 sm:px-5 py-2 rounded-2xl shadow-inner">--:--</span>
                        <p id="timeRemaining" class="text-sm font-semibold text-gray-600 mt-2 flex items-center justify-center md:justify-end gap-1">menghitung...</p>
                    </div>
                </div>
            </div>

            <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6" id="prayerGrid"></div>
            <div class="text-center mt-10 text-sm text-gray-500 flex items-center justify-center gap-2 reveal px-4">
                <svg class="mdi-icon" width="24" height="24" aria-hidden="true"><use href="#i-info"/></svg>
                Jadwal berdasarkan koordinat sekolah. Waktu sholat menggunakan WIB & metode Kemenag
            </div>
        </div>
    </section>

    <!-- Fitur Sekolah -->
    <section class="max-w-6xl mx-auto px-5 pb-20">
        <div class="grid sm:grid-cols-2 md:grid-cols-3 gap-7">
            <div class="bg-white/90 rounded-2xl p-6 shadow-lg text-center hover:shadow-xl transition-fast transform hover:-translate-y-2 reveal border border-sand">
                <svg class="mdi-icon mx-auto text-teal-700 mb-3" width="48" height="48" aria-hidden="true"><use href="#i-report"/></svg>
                <h3 class="font-display text-xl font-bold text-gray-800">Laporan Otomatis</h3>
                <p class="text-gray-600 mt-2">Rekap kehadiran sholat per kelas & per individu, siap cetak untuk wali kelas.</p>
            </div>
            <div class="bg-white/90 rounded-2xl p-6 shadow-lg text-center hover:shadow-xl transition-fast transform hover:-translate-y-2 reveal delay-100 border border-sand">
                <svg class="mdi-icon mx-auto text-gold-600 mb-3" width="48" height="48" aria-hidden="true"><use href="#i-bell"/></svg>
                <h3 class="font-display text-xl font-bold text-gray-800">Notifikasi Pengingat</h3>
                <p class="text-gray-600 mt-2">Siswa & guru dapat notifikasi waktu sholat via WhatsApp/Telegram terintegrasi.</p>
            </div>
            <div class="bg-white/90 rounded-2xl p-6 shadow-lg text-center hover:shadow-xl transition-fast transform hover:-translate-y-2 reveal delay-150 border border-sand sm:col-span-2 md:col-span-1">
                <svg class="mdi-icon mx-auto text-teal-700 mb-3" width="48" height="48" aria-hidden="true"><use href="#i-shield"/></svg>
                <h3 class="font-display text-xl font-bold text-gray-800">Verifikasi Lokasi</h3>
                <p class="text-gray-600 mt-2">Absensi berbasis GPS & QR Code masjid sekolah, akurasi tinggi.</p>
            </div>
        </div>
    </section>

    <!-- Footer -->
    <footer class="bg-teal-900 text-teal-100 py-10 mt-8 border-t border-gold-500/30">
        <div class="max-w-6xl mx-auto px-5 text-center">
            <p class="text-sm mb-5">Platform Absensi Sholat Digital untuk Sekolah Islam</p>
            <p class="text-xs text-teal-300 font-mono-brand">Powered by API Aladhan · Sholatify Sekolah | Membangun Generasi Sholeh dengan Kedisiplinan Ibadah</p>
        </div>
    </footer>

    <script>
        // ---------- Konfigurasi ----------
        const CONFIG = {
            lat: -0.227819,
            lng: 100.626617,
            method: 20,
            timezone: 'Asia/Jakarta',
            tickMs: 30000,
        };

        const PRAYER_ORDER = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
        const PRAYERS = [
            { key: 'Imsak',   label: 'Imsak',   icon: 'i-night',       bg: 'bg-teal-50/80',  border: 'border-teal-200' },
            { key: 'Fajr',    label: 'Subuh',   icon: 'i-sunrise',     bg: 'bg-gold-50/80',  border: 'border-gold-200' },
            { key: 'Dhuhr',   label: 'Dzuhur',  icon: 'i-sun-clock',   bg: 'bg-gold-50/80',  border: 'border-gold-200' },
            { key: 'Asr',     label: 'Ashar',   icon: 'i-sunset-down', bg: 'bg-gold-50/80',  border: 'border-gold-200' },
            { key: 'Maghrib', label: 'Maghrib', icon: 'i-sunset',      bg: 'bg-rose-50/80',  border: 'border-rose-200' },
            { key: 'Isha',    label: 'Isya',    icon: 'i-night-sky',   bg: 'bg-teal-100/80', border: 'border-teal-300' },
        ];

        const icon = (id, size = 24, cls = '') =>
            `<svg class="mdi-icon ${cls}" width="${size}" height="${size}" aria-hidden="true"><use href="#${id}"/></svg>`;

        // ---------- Elemen DOM ----------
        const $ = (id) => document.getElementById(id);
        const el = {
            loading: $('loadingPrayers'), error: $('errorMessage'), errorDetail: $('errorDetail'),
            retryBtn: $('retryBtn'), content: $('prayerContent'), grid: $('prayerGrid'),
            gregorian: $('gregorianDate'), hijri: $('hijriDate'),
            nextName: $('nextPrayerName'), nextTime: $('nextPrayerTime'), remaining: $('timeRemaining'),
        };

        // ---------- Helper waktu (WIB) ----------
        function getWIBParts(date = new Date()) {
            const parts = new Intl.DateTimeFormat('en-GB', {
                timeZone: CONFIG.timezone,
                day: '2-digit', month: '2-digit', year: 'numeric',
                hour: '2-digit', minute: '2-digit', hour12: false,
            }).formatToParts(date);
            const get = (type) => parts.find((p) => p.type === type).value;
            return {
                day: get('day'), month: get('month'), year: get('year'),
                hour: Number(get('hour')) % 24, minute: Number(get('minute')),
            };
        }

        // Format DD-MM-YYYY sesuai API Aladhan
        const getTodayWIB = () => {
            const { day, month, year } = getWIBParts();
            return `${day}-${month}-${year}`;
        };

        const getNowMinutes = () => {
            const { hour, minute } = getWIBParts();
            return hour * 60 + minute;
        };

        const toMinutes = (str) => {
            const [h, m] = str.split(':').map(Number);
            return h * 60 + m;
        };

        function formatRemaining(diff) {
            if (diff <= 0) return 'Waktu sholat! Segera absen.';
            const h = Math.floor(diff / 60);
            const m = diff % 60;
            if (h === 0) return `${m} menit lagi`;
            if (m === 0) return `${h} jam lagi`;
            return `${h} jam ${m} menit lagi`;
        }

        function getNextPrayer(timings, nowMin) {
            for (const key of PRAYER_ORDER) {
                const time = timings[key];
                if (time && toMinutes(time) > nowMin) return { key, time, targetMin: toMinutes(time) };
            }
            // Semua sholat hari ini lewat -> Subuh besok
            const key = PRAYER_ORDER[0];
            return { key, time: timings[key], targetMin: toMinutes(timings[key]) + 1440 };
        }

        // ---------- Render ----------
        function renderPrayerCards(timings) {
            el.grid.innerHTML = PRAYERS.map((p) => `
                <div class="prayer-card ${p.bg} border ${p.border} rounded-2xl p-5 shadow-md flex justify-between items-center">
                    <div class="flex items-center gap-3">
                        <div class="bg-white rounded-full p-2 shadow-sm">${icon(p.icon, 28)}</div>
                        <div>
                            <p class="text-xs font-bold text-gray-500 uppercase">${p.label}</p>
                            <p class="text-2xl font-mono-brand font-bold text-gray-800">${timings[p.key] || '--:--'}</p>
                        </div>
                    </div>
                    ${icon('i-chevron', 24, 'text-teal-500')}
                </div>`).join('');
        }

        function renderDates(hijri) {
            el.gregorian.textContent = new Date().toLocaleDateString('id-ID', {
                timeZone: CONFIG.timezone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
            });
            el.hijri.textContent = `${hijri.day} ${hijri.month.en} ${hijri.year} H`;
        }

        function updateCountdown(timings) {
            const nowMin = getNowMinutes();
            const next = getNextPrayer(timings, nowMin);
            el.nextName.textContent = PRAYERS.find((p) => p.key === next.key)?.label ?? next.key;
            el.nextTime.textContent = next.time;
            el.remaining.innerHTML = `${icon('i-timer', 16)} ${formatRemaining(next.targetMin - nowMin)}`;
        }

        function showState(state, message = '') {
            el.loading.classList.toggle('hidden', state !== 'loading');
            el.error.classList.toggle('hidden', state !== 'error');
            el.content.classList.toggle('hidden', state !== 'content');
            if (state === 'error') el.errorDetail.textContent = message || 'Gagal memuat';
        }

        // ---------- Timer & ambil data ----------
        let timer = null;
        let loadedDate = null;

        function startTimer(timings) {
            clearInterval(timer);
            updateCountdown(timings);
            timer = setInterval(() => {
                if (getTodayWIB() !== loadedDate) return fetchSchedule();
                updateCountdown(timings);
            }, CONFIG.tickMs);
        }

        async function fetchSchedule() {
            showState('loading');
            try {
                const today = getTodayWIB();
                const params = new URLSearchParams({
                    latitude: CONFIG.lat, longitude: CONFIG.lng,
                    method: CONFIG.method, timezonestring: CONFIG.timezone,
                });
                const resp = await fetch(`https://api.aladhan.com/v1/timings/${today}?${params}`);
                if (!resp.ok) throw new Error('Gagal mengambil data');

                const json = await resp.json();
                if (json.code !== 200 || !json.data) throw new Error('Format API error');

                const { timings, date } = json.data;
                loadedDate = today;
                renderDates(date.hijri);
                renderPrayerCards(timings);
                startTimer(timings);
                showState('content');
            } catch (err) {
                console.error(err);
                clearInterval(timer);
                showState('error', err.message);
            }
        }

        // ---------- Reveal saat scroll ----------
        const revealObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (!entry.isIntersecting) return;
                entry.target.classList.add('visible');
                revealObserver.unobserve(entry.target);
            });
        }, { threshold: 0.1 });
        document.querySelectorAll('.reveal').forEach((node) => revealObserver.observe(node));

        // ---------- Navigasi ----------
        const ROUTES = { loginBtn: '/login', registerBtn: '/register', heroRegisterBtn: '/register' };
        Object.entries(ROUTES).forEach(([id, path]) =>
            $(id)?.addEventListener('click', () => { window.location.href = path; }));

        // ---------- Init ----------
        el.retryBtn.addEventListener('click', fetchSchedule);
        fetchSchedule();
    </script>
</body>
</html>